contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept parameters to drive different calls and values.
    // target - address to pass to sendMoney (may be address(this) or any address)
    // sendValue - amount of wei to send when calling sendMoney
    // callData - arbitrary bytes passed to sendMoney
    // payToC - amount of wei to send to c via its fallback (to trigger depositsCount increment)
    // withdrawAmount - amount attempted to withdraw via withdraw
    function run(address target, uint sendValue, bytes calldata callData, uint payToC, uint withdrawAmount) public payable {
        require(address(this).balance >= payToC + sendValue, "insufficient balance for test transfers");

        // Record initial observable state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalanceC = address(c).balance;
        uint beforeBalanceThis = address(this).balance;

        // 1) Send Ether to c to trigger fallback (this is a top-level state-changing call)
        // Use low-level call to send Ether to the contract's fallback external payable
        (bool sentToC, ) = address(c).call{value: payToC}("");
        // sending to fallback should not revert (fallback doesn't revert); record result

        // 2) As owner (this contract is owner), try sendMoney which uses low-level call from C
        // This may or may not succeed depending on target; we capture revert by try/catch
        bool sendMoneyReverted;
        try c.sendMoney(target, sendValue, callData) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // 3) Attempt withdraw with specified amount as owner
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Observables after operations
        uint afterDeposits = c.depositsCount();
        uint afterBalanceC = address(c).balance;
        uint afterBalanceThis = address(this).balance;

        // General rule asserted for all inputs:
        // - The fallback increments depositsCount exactly when a payable call with empty data is made (sentToC true)
        //   i.e., afterDeposits == beforeDeposits + (sentToC ? 1 : 0)
        // - The contract's balance changes by the net of payToC into C and any successful withdraw out of C
        //   i.e., afterBalanceC == beforeBalanceC + (sentToC ? payToC : 0) - (withdrawReverted ? 0 : withdrawAmount)
        // - As this contract is owner, calls to sendMoney and withdraw should NOT revert due to onlyOwner (they may revert for other reasons);
        //   however sendMoney may revert due to target behavior — we assert only that withdraw does not revert because withdraw transfers to msg.sender which is payable
        //   and should succeed unless C lacks funds; therefore we assert consistency between balances and revert flag for withdraw.

        assert(
            // depositsCount updated exactly by one if and only if we successfully sent Ether to c with empty data
            afterDeposits == beforeDeposits + (sentToC ? 1 : 0)
            // balance change of c accounts for the sent amount (if sent) and for the withdrawn amount if withdraw succeeded
            && afterBalanceC == beforeBalanceC + (sentToC ? payToC : 0) - (withdrawReverted ? 0 : withdrawAmount)
            // balance change observed by this contract matches complementary movement (ignoring other external transfers from sendMoney)
            && afterBalanceThis == beforeBalanceThis - (sentToC ? payToC : 0) + (withdrawReverted ? 0 : withdrawAmount)
        );
    }

    // Accept Ether if sendMoney targets this contract or withdraw sends Ether here
    receive() external payable { }
}

