contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test takes: target address to call withdraw on (addr), value to try to withdraw (val),
    // and an amount to send to C to set up balance (fund). The test contract is NOT the owner of c.
    function run(address addr, uint val, uint fund) public payable {
        require(address(this).balance >= fund);

        // Fund the contract C by sending Ether to its fallback which increments depositsCount.
        // We must send the exact fund amount from this contract to c.
        c.f{value: fund}();

        // Record balances before attempted withdraw
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Attempt to call withdraw on c as a non-owner (InvMutTest was not the deployer of C).
        bool reverted;
        try c.withdraw(val) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call, read balances again
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule: if the caller is not the owner then withdraw must revert and no Ether moves from C to this contract.
        // Since the test contract is not the owner, we assert that either the call reverted, or if it did not revert,
        // then C's balance decreased by exactly val and this contract's balance increased by exactly val.
        // Because we want to assert that non-owners cannot withdraw, and this contract is not owner, we assert revert must be true.
        assert(reverted && afterC == beforeC && afterThis == beforeThis);
    }

    receive() external payable {}
}

