contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // This test takes parameters to attempt withdrawals and sendMoney; it asserts that only the owner can perform withdrawals
    // and that withdraw/withdrawAll do not change depositsCount and decrease address(c).balance by at most the requested amount when they succeed.
    function run(address target, uint sendValue, uint withdrawValue, bytes calldata data) public payable {
        require(true);

        // capture before values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;
        uint beforeMyBalance = address(this).balance;

        // Try withdraw(uint)
        bool withdrewReverted;
        uint afterBalanceWithdraw = beforeBalance;
        try c.withdraw{value:0}(withdrawValue) {
            withdrewReverted = false;
            afterBalanceWithdraw = address(c).balance;
        } catch {
            withdrewReverted = true;
            afterBalanceWithdraw = address(c).balance;
        }

        // Try withdrawAll()
        bool withdrawAllReverted;
        uint afterBalanceWithdrawAll = afterBalanceWithdraw;
        try c.withdrawAll{value:0}() {
            withdrawAllReverted = false;
            afterBalanceWithdrawAll = address(c).balance;
        } catch {
            withdrawAllReverted = true;
            afterBalanceWithdrawAll = address(c).balance;
        }

        // Try sendMoney (may transfer out and call target)
        bool sendMoneyReverted;
        uint afterBalanceSend = afterBalanceWithdrawAll;
        // If we want to send Ether from this test to c before calling sendMoney, ensure balance; but we will call sendMoney with value sendValue from c's own funds so no value attached here.
        try c.sendMoney{value:0}(target, sendValue, data) {
            sendMoneyReverted = false;
            afterBalanceSend = address(c).balance;
        } catch {
            sendMoneyReverted = true;
            afterBalanceSend = address(c).balance;
        }

        // General rule asserted:
        // 1) withdraw/withdrawAll, when they do not revert, cannot increase depositsCount (they must leave it unchanged)
        // 2) when withdraw/withdrawAll succeed, the contract balance must not increase and must be <= beforeBalance (i.e., non-increasing)
        // 3) withdraw/withdrawAll succeed only if msg.sender is owner; since this test contract is not necessarily owner, we express that if they succeeded then balance decreased by at most requested amount(s).

        uint finalDeposits = c.depositsCount();
        uint finalBalance = afterBalanceSend;

        // Construct assertion combining these: if a withdraw or withdrawAll succeeded then depositsCount unchanged and finalBalance <= beforeBalance
        assert(
            // depositsCount never increases across these owner-only calls
            finalDeposits <= beforeDeposits
            // And if any of the withdraw calls succeeded then final balance is <= beforeBalance
            && (
                withdrewReverted || withdrawAllReverted || finalBalance <= beforeBalance
            )
            // Additionally, depositsCount must not change due to withdraw/sendMoney directly: ensure non-increase
            && finalDeposits == beforeDeposits
        );
    }

    // receive to allow this contract to accept Ether if tests send any
    receive() external payable {}
}

contract InvMutTest {
    C c;
