    // single public entry performing calls and asserting the invariant
    function run(address target, uint sendValue, uint withdrawValue, bytes calldata data) public payable {
        require(true);

        // observe before values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // try withdraw(uint)
        bool withdrewReverted;
        try c.withdraw(withdrawValue) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // try withdrawAll()
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // try sendMoney (may invoke external call from c)
        bool sendMoneyReverted;
        try c.sendMoney(target, sendValue, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // observe after values
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule:
        // - depositsCount is never increased by withdraw/withdrawAll/sendMoney (must be <= before)
        // - if either withdraw or withdrawAll succeeded (did not revert) then contract balance did not increase (afterBalance <= beforeBalance)
        // - and depositsCount remains exactly unchanged when a withdraw/withdrawAll succeeded (no depositsCount change on successful withdrawals)
        assert(
            // deposits never increases
            afterDeposits <= beforeDeposits
            // if any withdraw succeeded then balance non-increasing
            && (withdrewReverted && withdrawAllReverted || afterBalance <= beforeBalance)
            // if any withdraw succeeded then depositsCount unchanged
            && (withdrewReverted && withdrawAllReverted || afterDeposits == beforeDeposits)
        );
    }

    // allow receiving Ether in callbacks invoked by c
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes as inputs: target address for sendMoney, value to send from c, data payload,
    // and a selector to choose which function to invoke (0 = withdraw, 1 = withdrawAll, 2 = sendMoney).
    function run(address target, uint value, bytes calldata data, uint8 which) public payable {
        require(which <= 2, "which out of range");
        // read-before values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        bool reverted;
        // make the call selected. InvMutTest is NOT the owner of c (owner = c deployed by external sender),
        // so calls should revert due to onlyOwner modifier. We catch reverts to observe them.
        if (which == 0) {
            try c.withdraw(value) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (which == 1) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // for sendMoney we may attempt to send Ether from c to target; it's restricted by onlyOwner
            try c.sendMoney(target, value, data) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Observed after-values
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule: if call reverted then depositsCount and balance unchanged; if call did not revert then
        // caller was owner (which cannot be true in this test setup), but we still assert the invariant linking revert
        // to no state change. This avoids assuming who owner is. The assertion: reverted implies no change in depositsCount and balance.
        assert(reverted == ((afterDeposits == beforeDeposits && afterBalance == beforeBalance) ? true : reverted));
    }

    // accept Ether if needed by tests (not used here but provided)
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take amount to send to c (to trigger fallback) and a boolean chooseRevertCall which if true
    // will attempt a restricted call (withdraw) expected to revert when called by this contract.
    function run(uint amount, bool doRestrictedCall) public payable {
        require(address(this).balance >= amount, "insufficient balance to send");

        // read-before values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        bool withdrewReverted = false;
        // If requested, attempt a restricted call which should revert because onlyOwner is not this contract.
        if (doRestrictedCall) {
            try c.withdraw(0) {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        }

        // Now invoke fallback by sending Ether to c. This is a state-changing top-level call.
        // Use low-level transfer via call through the contract's external payable fallback by calling c with value.
        (bool sent, ) = address(c).call{value: amount}("");
        // sent indicates whether the fallback accepted the Ether.

        // read-after values
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule enforced by assert:
        // - If the ether transfer succeeded (sent == true) then depositsCount increased by exactly 1 and c's balance increased by amount.
        // - If the ether transfer failed (sent == false) then depositsCount and c balance unchanged by that transfer.
        // - Additionally, if the optional restricted call was made and it reverted, that revert did not change depositsCount nor c balance.
        assert(
            (
                sent &&
                afterDeposits == beforeDeposits + 1 &&
                afterBalance == beforeBalance + amount
            ) || (
                !sent &&
                afterDeposits == beforeDeposits &&
                afterBalance == beforeBalance
            )
            &&
            (!doRestrictedCall || (withdrewReverted && afterDeposits == beforeDeposits + (sent ? 1 : 0) && afterBalance == beforeBalance + (sent ? amount : 0)))
        );
    }

    // Allow test contract to receive Ether so it can fund runs
    receive() external payable { }
}

